const body = $json.body || $json;
const company = body.company_name || body.company || '';
const contact = body.contact_name || body.name || '';
const email = body.contact_email || body.email || '';
const platform = body.platform || 'email';
const profileUrl = body.profile_url || '';
const industry = body.industry || '';
const notes = body.notes || '';

if (!company && !contact) {
  return [{ json: { _error: true, message: 'company_name or contact_name required' } }];
}

const fields = {
  company_name: company || '(Unknown)',
  contact_name: contact || '(Unknown)',
  stage: 'New',
  notes: `Source: outreach\nPlatform: ${platform}\nProfile: ${profileUrl}\nIndustry: ${industry}\n${notes}`
};
if (email) fields.email = email;

return [{ json: { fields, company, contact, platform, profileUrl, industry, notes: fields.notes, _error: false } }];

const prospect = $('out-validate-prospect').first().json;
const recordId = $json.id || 'unknown';

const systemPrompt = `You are a sales research assistant for Cosmisk, a UGC (User Generated Content) agency in India. Your job is to research a prospect brand and draft a compelling, personalized outreach message.

The message should:
- Be concise (3-4 sentences max for DM, 5-6 for email)
- Reference something specific about their brand/content
- Highlight how UGC can help their specific business
- Include a soft CTA (offer a free strategy call or sample script)
- Sound human, not salesy
- Match the platform tone (Instagram DM = casual, Email = slightly more formal, LinkedIn = professional)`;

const userPrompt = `Research and draft an outreach message for:

Company: ${prospect.company}
Contact: ${prospect.contact}
Platform: ${prospect.platform}
Profile/Website: ${prospect.profileUrl || 'not provided'}
Industry: ${prospect.industry || 'not specified'}

Draft the outreach message for ${prospect.platform}. Also provide:
1. A brief research summary (2-3 bullet points about the brand)
2. The outreach message
3. A suggested follow-up message (for 3 days later)

Format as JSON:
{
  "research": "bullet points about the brand",
  "message": "the outreach message",
  "follow_up": "the follow-up message",
  "subject_line": "email subject if platform is email, otherwise null"
}`;

return [{ json: { systemPrompt, userPrompt, recordId, prospect } }];

const geminiResult = $json;
const prev = $('out-build-research-prompt').first().json;
const recordId = prev.recordId;
const prospect = prev.prospect;

let research = '';
let message = '';
let followUp = '';
let subjectLine = '';

try {
  const text = geminiResult?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    research = parsed.research || '';
    message = parsed.message || '';
    followUp = parsed.follow_up || '';
    subjectLine = parsed.subject_line || '';
  } else {
    message = text;
  }
} catch (e) {
  message = `Hi ${prospect.contact || 'there'}, I came across ${prospect.company || 'your brand'} and love what you're doing. We help brands like yours create authentic UGC content that drives real results. Would you be open to a quick 15-min call to explore how we could help?`;
  followUp = `Hey ${prospect.contact || 'there'}, just following up on my earlier message. We recently helped a ${prospect.industry || 'similar'} brand increase their ad performance by 40% with UGC. Happy to share the case study if you're interested!`;
}

const notesUpdate = `\n\n--- AI Research ---\n${research}\n\n--- Draft Message (${prospect.platform}) ---\n${message}\n\n--- Follow-up Draft ---\n${followUp}`;

const originalNotes = prospect.notes || `Platform: ${prospect.platform}\nProfile: ${prospect.profileUrl || ''}\nIndustry: ${prospect.industry || ''}`;
const fullNotes = originalNotes + notesUpdate;
const followUpDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

const slackMsg = `:mag: *New Prospect Researched*\n\n` +
  `*Company:* ${prospect.company}\n` +
  `*Contact:* ${prospect.contact}\n` +
  `*Platform:* ${prospect.platform}\n` +
  `*Profile:* ${prospect.profileUrl || 'N/A'}\n\n` +
  `*Research:*\n${research}\n\n` +
  `*Draft Message:*\n\`\`\`${message}\`\`\`\n\n` +
  (subjectLine ? `*Subject:* ${subjectLine}\n\n` : '') +
  `*Follow-up Draft:*\n\`\`\`${followUp}\`\`\`\n\n` +
  `_Copy the message above and send it on ${prospect.platform}. Then use /mark-outreach to update status._`;

return [{ json: { recordId, slackMsg, prospect, patchBody: { fields: { notes: fullNotes, stage: 'contacted', next_follow_up: followUpDate } } } }];

const body = $json.body || $json;
const leadId = body.lead_id || body.record_id || '';
const status = body.status || '';
const notes = body.notes || '';

if (!leadId || !status) {
  return [{ json: { _error: true, message: 'lead_id and status required' } }];
}

const stageMap = {
  'contacted': 'contacted',
  'responded': 'follow_up',
  'interested': 'follow_up',
  'not_interested': 'lost'
};
const stage = stageMap[status] || 'follow_up';

const patchBody = { fields: { stage } };
if (notes) patchBody.fields.notes = notes;
if (status === 'interested') {
  patchBody.fields.next_follow_up = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().split('T')[0];
}

return [{ json: { leadId, patchBody, status, _error: false } }];

const response = $json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { hasFollowups: false, count: 0, prospects: [] } }];
}

const prospects = records.map(r => ({
  id: r.id,
  company: r.fields.company_name || '',
  contact: r.fields.contact_name || '',
  email: r.fields.email || '',
  channel: r.fields.channel || 'email',
  notes: r.fields.notes || '',
  lastContact: r.fields.next_follow_up || ''
}));

return [{ json: { hasFollowups: true, count: prospects.length, prospects } }];

const data = $json;
const prospects = data.prospects;

const systemPrompt = `You are a sales follow-up assistant for Cosmisk, a UGC agency. Generate personalized follow-up messages for prospects who haven't responded to initial outreach. Messages should be brief, add new value (case study mention, industry insight, or limited offer), and have a clear CTA.`;

let prospectsList = prospects.map((p, i) => 
  `${i + 1}. ${p.company} (${p.contact}) - ${p.channel} - Last contacted: ${p.lastContact}
Previous notes: ${(p.notes || '').substring(0, 200)}`
).join('

');

const userPrompt = `Generate follow-up messages for these ${prospects.length} prospects:

${prospectsList}

For each, provide a JSON array:
[
  { "record_id": "recXXX", "message": "follow-up text", "subject": "email subject or null" }
]

Use the actual record IDs from the prospect data. The record IDs are:
${prospects.map(p => `- ${p.company}: ${p.id}`).join('
')}`;

return [{ json: { systemPrompt, userPrompt, prospects } }];

const geminiResult = $json;
const prospects = $('out-build-followup-prompt').first().json.prospects;

let followups = [];
try {
  const text = geminiResult?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const jsonMatch = text.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    followups = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  followups = prospects.map(p => ({
    record_id: p.id,
    message: `Hi ${p.contact || 'there'}, just following up on my earlier message about how UGC content could help ${p.company || 'your brand'}. We recently helped a brand in your space see 3x better ad performance with authentic creator content. Would love to share the case study - are you free for a quick 10-min call this week?`,
    subject: null
  }));
}

if (followups.length > 0 && !followups[0].record_id && prospects.length === followups.length) {
  followups = followups.map((f, i) => ({ ...f, record_id: prospects[i].id }));
}

let slackMsg = `:repeat: *Daily Outreach Follow-ups (${followups.length} prospects)*\n\n`;
followups.forEach((f, i) => {
  const p = prospects.find(pr => pr.id === f.record_id) || prospects[i] || {};
  slackMsg += `*${i + 1}. ${p.company || 'Unknown'}* (${p.contact || ''}) - ${p.channel || 'email'}\n`;
  if (f.subject) slackMsg += `Subject: ${f.subject}\n`;
  slackMsg += `\`\`\`${f.message}\`\`\`\n\n`;
});
slackMsg += `_Copy and send these follow-ups, then use /mark-outreach to update status._`;

const nextDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const updates = followups.map(f => ({
  id: f.record_id,
  fields: { next_follow_up: nextDate }
}));

return [{ json: { slackMsg, updates, count: followups.length } }];
